"use client";

import { useMemo, useState } from "react";
import { QiArchive, QiDeleteTrash, QiCircleDownload, QiPencil, QiCopy, QiMoreVert, QiSearch } from "@/components/qiguan/icons";
import { QIconComponent } from "@/components/qiguan/icons";
import { Focusable } from "react-aria-components";
import type { Selection } from "react-aria-components";
import {
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table";
import type { ColumnDef, PaginationState, SortingState } from "@tanstack/react-table";
import type { ReactNode } from "react";

import { Checkbox } from "@/components/base/checkbox/checkbox";
import { CARD_SURFACE } from "@/components/application/card-surface";
import { IconButton } from "@/components/base/buttons/icon-button";
import {
  Dropdown,
  DropdownGroup,
  DropdownItem,
  DropdownPopover,
  DropdownTrigger,
} from "@/components/base/dropdown/dropdown";
import { InputBase } from "@/components/base/input/input";
import { Pagination } from "@/components/base/pagination/pagination";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "@/components/base/segmented-control/segmented-control";
import { Select, SelectItem } from "@/components/base/select/select";
import {
  SEARCH_PILL_SURFACE,
  unsetTriggerClass,
} from "@/components/application/filters/filter-appearance";
import {
  Table,
  TableBody,
  TableCell,
  TableColumn,
  TableHeader,
  TableRow,
} from "@/components/base/table/table";
import type { TableSize } from "@/components/base/table/table";
import { Tooltip, TooltipTrigger } from "@/components/base/tooltip/tooltip";
import { ChevronSortDown } from "@/components/foundations/icons/chevrons";
import { cx } from "@/lib/cx";
import { formatThousands } from "@/lib/format-number";

/**
 * 通用台账表格 —— 数据驱动的表格，供多个业务页复用。
 *
 * 为什么单独抽一个而不是每页各写一遍：`data-table.tsx` 是**固定种子的客户表**，
 * 列和数据都写死在组件里。风险事件 / 客户管理 / 策略规则三页需要的是"同一套
 * 视觉与交互（筛选 → 搜索 → 排序 → 分页 → 行操作），换一份列和数据"，
 * 复制三遍只会让三处的分页逻辑各自漂移。
 *
 * 本组件只管**呈现与交互**，不关心数据从哪来：调用方把列定义和行数据传进来。
 * 列宽、可排序性、行操作菜单都通过 props 声明。
 */

/** 一列的声明。`sortValue` 不给就表示这一列不可排序。 */
export type RecordColumn<T> = {
  id: string;
  header: string;
  /** Tailwind 宽度类，例如 `w-[240px]`。不写就按内容自适应。 */
  width?: string;
  /** 单元格内容。 */
  cell: (row: T) => ReactNode;
  /** 排序取值。给字符串就按字典序，给数字就按数值。 */
  sortValue?: (row: T) => string | number;
  /** 标记行首列：react-aria 会把它读成行标题，视觉上也是重点关注列。 */
  isRowHeader?: boolean;
};

/** 工具栏上的一个下拉筛选。 */
export type RecordFilter<T> = {
  id: string;
  ariaLabel: string;
  allLabel: string;
  options: readonly string[];
  /** 判断某行是否命中该筛选项。 */
  match: (row: T, value: string) => boolean;
};

export type RecordRowAction = {
  icon: QIconComponent;
  label: string;
};

/** 行内图标按钮，从左到右。默认与 data-table 的客户表一致。 */
export const DEFAULT_INLINE_ACTIONS: readonly RecordRowAction[] = [
  { icon: QiDeleteTrash, label: "删除" },
  { icon: QiPencil, label: "编辑" },
];

/** 「⋮」菜单里的动作。 */
export const DEFAULT_MENU_ACTIONS: readonly RecordRowAction[] = [
  { icon: QiCopy, label: "复制行" },
  { icon: QiCircleDownload, label: "导出" },
  { icon: QiArchive, label: "归档" },
];

/** 复选框列宽（含 12px 内边距）。多选时加到 `minWidth` 上，否则最小宽度会把
 *  最后那列挤掉一点。 */
const SELECTION_COLUMN_WIDTH = 44;

/**
 * 「操作」列固定在右侧 —— 台账列多、横向滚动时，行操作按钮不跟着滚走。
 *
 * 样式本体在 `styles/globals.css` 的 `.bui-sticky-col`（`border-collapse:
 * separate` 与背景 `inherit` 的来龙去脉都在那边写清楚了）。这里只负责
 * **把类同时挂到表头和表体** —— 少挂哪一侧，那一侧就照旧跟着滚。
 *
 * 固定列必须有确定宽度，否则内容滚到一半时列宽会跳，所以宽度走常量。
 */
const ACTIONS_COLUMN_WIDTH = "w-[132px]";
const STICKY_ACTIONS_HEAD = "bui-sticky-col bui-sticky-col-head";
const STICKY_ACTIONS_CELL = "bui-sticky-col";

/** 带 tooltip 的图标动作按钮：`IconButton` 是原生 button，包一层 `Focusable`
 *  才能挂上 react-aria 的 TooltipTrigger。 */
function RowActionButton({ icon, label }: { icon: QIconComponent; label: string }) {
  return (
    <TooltipTrigger delay={200}>
      <Focusable>
        <IconButton icon={icon} size="small" aria-label={label} />
      </Focusable>
      <Tooltip size="md">{label}</Tooltip>
    </TooltipTrigger>
  );
}

/** 「⋮」行操作菜单。触发器手写样式以对齐 IconButton 的 small secondary，
 *  因为把真的 IconButton 塞进 DropdownTrigger 会嵌套 <button>。 */
function RowMoreMenu({ label, actions }: { label: string; actions: readonly RecordRowAction[] }) {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <Dropdown isOpen={isOpen} onOpenChange={setIsOpen}>
      <TooltipTrigger delay={200}>
        <DropdownTrigger
          aria-label={`${label} 的更多操作`}
          className={cx(
            "relative inline-flex size-8 shrink-0 items-center justify-center rounded-2lg",
            "border border-border-button-default bg-background-primary-default text-foreground-icon-primary shadow-xs",
            "transition-[background-color,border-color,box-shadow,color] duration-150 ease",
            "hover:border-border-button-hover hover:bg-background-primary-hover",
            isOpen && "border-border-button-active bg-background-primary-active",
          )}
        >
          <QiMoreVert className="size-4 shrink-0" aria-hidden />
        </DropdownTrigger>
        <Tooltip size="md">更多操作</Tooltip>
      </TooltipTrigger>
      <DropdownPopover
        aria-label={`${label} 的更多操作`}
        placement="bottom end"
        className="w-[220px] p-2"
      >
        <DropdownGroup>
          {actions.map(({ icon: Icon, label: actionLabel }) => (
            <DropdownItem
              key={actionLabel}
              onSelect={() => setIsOpen(false)}
              className="px-2 py-1.5"
            >
              <Icon className="size-[18px] shrink-0 text-foreground-icon-secondary" aria-hidden />
              <span className="truncate text-body-medium whitespace-nowrap text-text-primary">
                {actionLabel}
              </span>
            </DropdownItem>
          ))}
        </DropdownGroup>
      </DropdownPopover>
    </Dropdown>
  );
}

function SortChevron({ dir }: { dir: false | "asc" | "desc" }) {
  return (
    <ChevronSortDown
      className={cx(
        "size-6 shrink-0 transition-[transform,color] duration-150",
        dir === "asc" && "rotate-180",
        dir ? "text-text-secondary" : "text-text-tertiary",
      )}
    />
  );
}

export function RecordTable<T extends { id: string }>({
  ariaLabel,
  unit,
  columns,
  rows,
  filters = [],
  searchText,
  searchPlaceholder = "搜索",
  pageSize = 8,
  minWidth = 1000,
  emptyMessage = "没有符合筛选条件的数据。",
  showActions = true,
  inlineActions = DEFAULT_INLINE_ACTIONS,
  menuActions = DEFAULT_MENU_ACTIONS,
  rowMenuLabel,
  showSizeToggle = true,
  selectable = false,
}: {
  /** 表格的无障碍名称，同时用于空状态文案。 */
  ariaLabel: string;
  /** 结果总数的量词，例如「条」。 */
  unit: string;
  columns: RecordColumn<T>[];
  rows: T[];
  filters?: readonly RecordFilter<T>[];
  /** 搜索框匹配的文本。不给就不显示搜索框。 */
  searchText?: (row: T) => string;
  searchPlaceholder?: string;
  pageSize?: number;
  minWidth?: number;
  emptyMessage?: string;
  /** 是否显示「操作」列。 */
  showActions?: boolean;
  /** 行内图标按钮，从左到右。 */
  inlineActions?: readonly RecordRowAction[];
  /** 「⋮」菜单里的动作。传空数组则只剩图标按钮。 */
  menuActions?: readonly RecordRowAction[];
  /** 行操作菜单的 aria-label 前缀，通常用行标题。 */
  rowMenuLabel?: (row: T) => string;
  showSizeToggle?: boolean;
  /**
   * 多选模式：表头出现全选框，每行出现复选框，工具栏显示已选条数。
   *
   * 复选框列的 `<Column>` / `<Cell>` 必须由我们自己声明。react-aria 有一个
   * 自动插入选择列的开关（`showSelectionCheckboxes`），但**默认是关的**，
   * 开了之后它 unshift 出来的那列 `rendered` 是 `null`（表头会是空的），
   * 得再声明一列去填，反而多出一列。手动声明只多 10 行、语义也更清楚。
   *
   * 选中状态只在组件内部（点复选框才变），不做受控 —— 这一层的调用方
   * 要的都是「选几条然后执行批量操作」，没有把选中集合提到外面的场景。
   */
  selectable?: boolean;
}) {
  const [sorting, setSorting] = useState<SortingState>([]);
  const [pagination, setPagination] = useState<PaginationState>({ pageIndex: 0, pageSize });
  const [size, setSize] = useState<TableSize>("md");
  const [query, setQuery] = useState("");
  const [filterState, setFilterState] = useState<Record<string, string>>({});
  const [selectedKeys, setSelectedKeys] = useState<Selection>(new Set());

  const data = useMemo(() => {
    const q = query.trim().toLowerCase();
    return rows.filter((row) => {
      for (const f of filters) {
        const value = filterState[f.id];
        if (value && value !== "all" && !f.match(row, value)) return false;
      }
      if (q !== "" && searchText && !searchText(row).toLowerCase().includes(q)) return false;
      return true;
    });
  }, [rows, filters, filterState, query, searchText]);

  const tableColumns = useMemo<ColumnDef<T>[]>(() => {
    const defs: ColumnDef<T>[] = columns.map((col) => ({
      id: col.id,
      // 每个数据列都挂 accessorFn：排序要读它，单元格渲染则直接用 col.cell。
      // 不给 accessor 的话这一列会被 tanstack 当成 display 列，排序拿不到值。
      accessorFn: (row: T) => (col.sortValue ? col.sortValue(row) : ""),
      header: col.header,
      enableSorting: Boolean(col.sortValue),
      cell: ({ row }) => col.cell(row.original),
    }));
    if (showActions) {
      defs.push({
        id: "actions",
        accessorFn: () => "",
        header: "操作",
        enableSorting: false,
        cell: ({ row }) => (
          <div className="flex items-center justify-end gap-2.5">
            {inlineActions.map((action) => (
              <RowActionButton
                key={action.label}
                icon={action.icon}
                label={action.label}
              />
            ))}
            {menuActions.length > 0 && (
              <RowMoreMenu
                label={rowMenuLabel ? rowMenuLabel(row.original) : "该项"}
                actions={menuActions}
              />
            )}
          </div>
        ),
      });
    }
    return defs;
  }, [columns, showActions, inlineActions, menuActions, rowMenuLabel]);

  const table = useReactTable({
    data,
    columns: tableColumns,
    getRowId: (row) => row.id,
    state: { sorting, pagination },
    onSortingChange: setSorting,
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
  });

  const headers = table.getHeaderGroups()[0].headers;
  const pageRows = table.getRowModel().rows;
  const totalPages = table.getPageCount();
  const widthOf = (id: string) => columns.find((c) => c.id === id)?.width;
  const rowHeaderId = columns.find((c) => c.isRowHeader)?.id;

  /** `Selection` 是 `"all" | Set<Key>` 的联合类型，两种都要能数。 */
  const selectedCount = selectedKeys === "all" ? data.length : selectedKeys.size;

  const resetPage = () => table.setPageIndex(0);

  return (
    <section
      className={cx(
        // 卡片表面取自共享常量：与查询卡（`FilterBar`）、KPI 卡（`StatCards`）同一种。
        // ⚠️ 这里**故意不给横向内衬**（不用 `CARD_INSET`）：横向那 10px 由工具栏
        // 和每个单元格的 `px-2.5` 各自提供。卡片上再补一层，单元格会变成 20px
        // 内缩，反而与查询卡的 10px 对不齐 —— 卡片里所有文字要落在同一条竖线上。
        "flex w-full flex-col pt-2.5",
        CARD_SURFACE,
        totalPages > 1 ? "pb-2.5" : "pb-0",
      )}
    >
      {/* 工具栏：左侧结果总数，右侧筛选 + 搜索 */}
      <div className="flex w-full flex-col items-start gap-3 px-2.5 py-1 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-col justify-center">
          <p className="text-body-medium whitespace-nowrap text-text-tertiary">
            {selectedCount > 0 ? "已选" : "结果总数"}
          </p>
          <p className="text-body-medium whitespace-nowrap text-text-primary">
            {formatThousands(selectedCount > 0 ? selectedCount : data.length)} {unit}
          </p>
        </div>
        {selectedCount > 0 && (
          <button
            type="button"
            onClick={() => setSelectedKeys(new Set())}
            className="cursor-pointer rounded-2lg px-1.5 py-1 text-body-medium text-accent-600 outline-none transition-colors hover:bg-accent-50 focus-visible:ring-2 focus-visible:ring-border-focus-ring"
          >
            清空选择
          </button>
        )}
        <div className="-mx-2.5 flex w-[calc(100%+1.25rem)] items-center gap-2.5 overflow-x-auto px-2.5 sm:mx-0 sm:w-auto sm:flex-wrap sm:justify-end sm:overflow-visible sm:px-0">
          {filters.map((f) => (
            <Select
              key={f.id}
              aria-label={f.ariaLabel}
              className="shrink-0"
              popoverClassName="min-w-40"
              selectedKey={filterState[f.id] ?? "all"}
              onSelectionChange={(key) => {
                setFilterState((prev) => ({ ...prev, [f.id]: String(key) }));
                resetPage();
              }}
              // 「全部」= 未筛选 → 与搜索框的 placeholder 同色（同一条规则，
              // 见 `components/application/filters/filter-appearance.ts`）。
              triggerClassName={unsetTriggerClass(filterState[f.id] ?? "all")}
            >
              <SelectItem id="all" textValue={f.allLabel}>
                {f.allLabel}
              </SelectItem>
              {f.options.map((option) => (
                <SelectItem key={option} id={option} textValue={option}>
                  {option}
                </SelectItem>
              ))}
            </Select>
          ))}
          {searchText && (
            <InputBase
              aria-label={searchPlaceholder}
              placeholder={searchPlaceholder}
              leadingIcon={QiSearch}
              value={query}
              onChange={(e) => {
                setQuery(e.target.value);
                resetPage();
              }}
              fieldClassName={cx(
                SEARCH_PILL_SURFACE,
                "min-w-[153px] flex-1 sm:w-[153px] sm:min-w-0 sm:flex-none",
              )}
            />
          )}
          {showSizeToggle && (
            // 密度是这张表的「视图选项」，和筛选/搜索是同一类东西，所以放同一条
            // 工具条里。⚠️ 曾经挂在 `</section>` 之后（卡片外面、页面最底部）：
            // 卡片外的那个位置要先滚完整个列表（500px 视口下要滚 ~500px）才看得见，
            // 用户反馈「列表底部的标准紧凑点击不了」就是这个原因 —— 不是控件坏了，
            // 是它根本不在第一屏、且看着像列表残渣。
            <SegmentedControl
              aria-label="表格密度"
              className="shrink-0"
              selectedKeys={new Set([size])}
              onSelectionChange={(keys) => {
                const next = [...keys][0];
                if (next) setSize(next as TableSize);
              }}
            >
              <SegmentedControlItem id="md">标准</SegmentedControlItem>
              <SegmentedControlItem id="sm">紧凑</SegmentedControlItem>
            </SegmentedControl>
          )}
        </div>
      </div>

      <div className="mt-2">
        <Table
          aria-label={ariaLabel}
          size={size}
          selectionMode={selectable ? "multiple" : "none"}
          selectedKeys={selectable ? selectedKeys : undefined}
          onSelectionChange={selectable ? setSelectedKeys : undefined}
          style={{ minWidth: selectable ? minWidth + SELECTION_COLUMN_WIDTH : minWidth }}
        >
          <TableHeader>
            {/* 复选框列必须由我们自己声明：react-aria 的自动选择列是个默认关闭
                的开关（`showSelectionCheckboxes`），真开出来表头还是空的。 */}
            {selectable && (
              <TableColumn id="selection" className="w-11">
                <Checkbox slot="selection" />
              </TableColumn>
            )}
            {headers.map((header) => {
              const id = header.column.id;
              const label = flexRender(header.column.columnDef.header, header.getContext());
              return (
                <TableColumn
                  key={header.id}
                  id={header.id}
                  isRowHeader={id === rowHeaderId}
                  className={cx(
                    widthOf(id) ?? (id === "actions" ? ACTIONS_COLUMN_WIDTH : undefined),
                    id === "actions" && STICKY_ACTIONS_HEAD,
                  )}
                >
                  {header.column.getCanSort() ? (
                    <button
                      type="button"
                      onClick={header.column.getToggleSortingHandler()}
                      className="flex cursor-pointer items-center gap-0.5"
                    >
                      {label}
                      <SortChevron dir={header.column.getIsSorted()} />
                    </button>
                  ) : (
                    label
                  )}
                </TableColumn>
              );
            })}
          </TableHeader>
          <TableBody
            renderEmptyState={() => (
              <div className="flex h-40 items-center justify-center text-body-medium text-text-tertiary">
                {emptyMessage}
              </div>
            )}
          >
            {pageRows.map((row) => (
              <TableRow key={row.id} id={row.id}>
                {selectable && (
                  <TableCell className="w-11">
                    <Checkbox
                      slot="selection"
                      aria-label={`选择 ${rowMenuLabel ? rowMenuLabel(row.original) : "该行"}`}
                    />
                  </TableCell>
                )}
                {row.getVisibleCells().map((cell) => (
                  <TableCell
                    key={cell.id}
                    className={cx(
                      widthOf(cell.column.id),
                      cell.column.id === "actions" && STICKY_ACTIONS_CELL,
                    )}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      {totalPages > 1 && (
        <div className="border-t border-separator-border px-2.5 pt-2.5">
          <Pagination
            page={pagination.pageIndex + 1}
            totalPages={totalPages}
            onChange={(p) => table.setPageIndex(p - 1)}
          />
        </div>
      )}
    </section>
  );
}
